import { Injectable } from "@angular/core";
import { SuperService } from "./super.service";
import { ActividadEconomica } from "../models/actividad.economica";

@Injectable({
    providedIn:'root'
})
export class ActividadEconomicaService extends SuperService<ActividadEconomica> {
    protected model = 'actividades_economicas';
    protected columns: (keyof ActividadEconomica)[] = [
        'codigo',
        'nombre',
        'descripcion',
        'sector',
        'subsector',
        'rama',
        'subrama',
        'productos',
        'deleted_at',
        'created_at'
    ]

    /**
     * Obtiene todas las actividades económicas activas
     *
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con la lista de actividades económicas
     */
    async getActividadesEconomicasActivas(loader = true): Promise<ActividadEconomica[]> {
        const response = await this.get(
            {
                conditionals: {
                    deleted_at: null,
                },
                loader
            }
        );
        return response.data || [];
    }

    /**
     * Busca actividades económicas por texto
     *
     * @param searchText - Texto a buscar en nombre o descripción
     * @param loader - Muestra loader global animado (por defecto true)
     * @returns Promise con las actividades económicas encontradas
     */
    async buscarActividades(searchText: string, loader = true): Promise<ActividadEconomica[]> {
        const response = await this.get(
            {
                conditionals: {
                    deleted_at: null,
                },
                search: searchText,
                loader
            }
        );
        return response.data || [];
    }
}